{"action":"edit","path":"toolformer_filter.py","old_text":"","new_text":"import numpy as np

def filter_api_calls(log_probs_empty, log_probs_call_only, log_probs_plus, tau_filter):
    # Validate inputs
    # Check tau_filter type and value
    if isinstance(tau_filter, bool):
        raise ValueError("tau_filter must not be boolean")
    try:
        tau = float(tau_filter)
    except (TypeError, ValueError):
        raise ValueError("tau_filter must be a finite nonnegative number")
    if np.isnan(tau) or np.isinf(tau) or tau < 0:
        raise ValueError("tau_filter must be finite and nonnegative")

    # Validate matrices
    for mat, name in [(log_probs_empty, 'log_probs_empty'),
                      (log_probs_call_only, 'log_probs_call_only'),
                      (log_probs_plus, 'log_probs_plus')]:
        if not isinstance(mat, (np.ndarray,)):
            raise ValueError(f"{name} must be a numpy array")
        if mat.ndim != 2:
            raise ValueError(f"{name} must be 2-dimensional")
        if mat.shape[0] == 0 or mat.shape[1] == 0:
            raise ValueError(f"{name} must not be empty")
        if not np.all(np.isfinite(mat)):
            raise ValueError(f"{name} contains nonfinite values")
        if np.any(mat > 0):
            raise ValueError(f"{name} contains positive values (must be nonpositive)")

    # Check shape consistency
    if not (log_probs_empty.shape == log_probs_call_only.shape == log_probs_plus.shape):
        raise ValueError("All input matrices must have the same shape")

    n_candidates, horizon = log_probs_empty.shape

    # Compute weights
    t = np.arange(horizon)  # offsets 0..horizon-1
    raw_weights = np.maximum(0, 1 - 0.2 * t)
    weight_sum = np.sum(raw_weights)
    if weight_sum == 0:
        raise ValueError("All weights are zero; horizon might be too large")
    norm_weights = raw_weights / weight_sum

    # Compute weighted losses (negative weighted log probabilities)
    loss_empty = -np.dot(log_probs_empty, norm_weights)   # shape (n_candidates,)
    loss_call_only = -np.dot(log_probs_call_only, norm_weights)
    loss_plus = -np.dot(log_probs_plus, norm_weights)

    L_minus = np.minimum(loss_empty, loss_call_only)
    margins = L_minus - loss_plus
    keep = margins >= tau

    return keep, margins"}
